19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE = 0.1;
21	
22	/** Applies a percentage surcharge, e.g. addSurcharge(100, 0.1) === 110. */
23	const addSurcharge = (amount: number, rate: number): number => amount * (1 + rate);
24	
25	/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
26	const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
27	
28	const BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
38	
39	const COMPONENT_TYPES = ["rune", "moonstone"];
40	const BLOCK_SIZE = 3;
41	const BLOCK_BASE_PREMIUM = 60;
42	
43	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
44	
45	const countByType = (items: Item[]): Map<string, number> => {
46	  const counts = new Map<string, number>();
47	
48	  for (const item of items) {
49	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
50	  }
51	
52	  return counts;
53	};
54	
55	/**
56	 * Alike components form a building block at the special premium, but only
57	 * when there are exactly BLOCK_SIZE of them.
58	 */
59	const componentsBasePremium = (items: Item[]): number => {
60	  let total = 0;
61	
62	  for (const [type, count] of countByType(items)) {
63	    total +=
64	      count === BLOCK_SIZE
65	        ? BLOCK_BASE_PREMIUM
66	        : count * BASE_PREMIUMS[type];
67	  }
68	
69	  return total;
70	};
71	
72	/** The policy base premium is the sum of the base premiums of its items. */
73	const policyBasePremium = (items: Item[]): number => {
74	  const mainItems = items.filter((item) => !isComponent(item));
75	  const components = items.filter(isComponent);
76	
77	  return (
78	    mainItems.reduce((sum, item) => sum + itemBasePremium(item), 0) +
79	    componentsBasePremium(components)
80	  );
81	};
82	
83	const quotePremium = (step: QuoteStep): number => {
84	  const premiumAfterFirstInsuranceSurcharge = addSurcharge(
85	    policyBasePremium(step.items),
86	    FIRST_INSURANCE_SURCHARGE,
87	  );
88	
89	  return roundUp(premiumAfterFirstInsuranceSurcharge + PROCESSING_FEE);
90	};
91	
92	export const runScenario = (scenario: Scenario): ScenarioResults => ({
93	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
94	});
